import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Deque<String> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            String op = sc.next();
            if (op.equals("push")) stack.addFirst(sc.next());
            else {
                String v = stack.pollFirst();
                System.out.println(v == null ? "empty" : v);
            }
        }
        System.out.println("rest=" + stack);
    }
}

