import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Integer> xs = new ArrayList<>();
        for (int i = 0; i < n; i++) xs.add(sc.nextInt());
        Iterator<Integer> it = xs.iterator();
        while (it.hasNext()) if (it.next() < 0) it.remove();
        System.out.println(xs);
        if (xs.isEmpty()) System.out.println("first=none last=none");
        else System.out.println("first=" + xs.getFirst() + " last=" + xs.getLast());
    }
}

