import java.util.*;

public class Main {
    /** 外側のインスタンスを要さないので static nested record。 */
    record Line(String name, int price) { }

    private int total;

    /** 外側の total に触るので inner class（static を付けない）。 */
    class Discount {
        int apply(int rate) {
            return total * (100 - rate) / 100;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Line> lines = new ArrayList<>();
        Main cart = new Main();
        for (int i = 0; i < n; i++) {
            Line line = new Line(sc.next(), sc.nextInt());
            lines.add(line);
            cart.total += line.price();
        }
        int rate = sc.nextInt();
        StringBuilder sb = new StringBuilder();
        for (Line line : lines) {
            if (sb.length() > 0) {
                sb.append(", ");
            }
            sb.append(line.name()).append("=").append(line.price());
        }
        System.out.println("lines=[" + sb + "]");
        System.out.println("total=" + cart.total);
        System.out.println("discounted=" + cart.new Discount().apply(rate));
    }
}

