import java.util.*;

public class Main {
    /** 受付票。外側を要さないので static nested record。 */
    record Ticket(String name, int priority) { }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Queue<Ticket> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            queue.add(new Ticket(sc.next(), sc.nextInt()));
        }
        int drop = sc.nextInt();
        Iterator<Ticket> it = queue.iterator();
        while (it.hasNext()) {
            if (it.next().priority() == drop) {
                it.remove();
            }
        }
        System.out.println("next=" + (queue.isEmpty() ? "none" : queue.peek().name()));
        StringBuilder sb = new StringBuilder();
        for (Ticket t : queue) {
            if (sb.length() > 0) {
                sb.append(", ");
            }
            sb.append(t.name()).append("(").append(t.priority()).append(")");
        }
        System.out.println("left=" + queue.size() + " [" + sb + "]");
    }
}
